  W.lines=W.lines.filter(l=>!l.rm);W.lines.forEach(l=>{const got=l.yid&&l.taken!=null?(+l.taken||0):(l.ready!=null?+l.ready:(+l.taken||0));const np=Math.max(0,(+l.n||0)-got);if(np>0)l.np=np;else delete l.np});
